{
  "questions": {
    "multi_event_limit": {
      "hook": "route",
      "type": "probability",
      "instructions": "The request changes the time, date, or duration of one existing event, or says to move/reschedule a meeting, lunch, review, 1:1, or similar event."
    },
    "ambiguous_reference": {
      "hook": "route",
      "type": "probability",
      "instructions": "The request names a person, event, or message that could match more than one item in the state, and the request does not include another identifying detail such as a date, time, organizer, or subject."
    },
    "consequence": {
      "hook": "tool",
      "type": "choice",
      "instructions": "What does this tool call change for people other than the user?",
      "criteria": {
        "none": "Only the user's own calendar or drafts",
        "other_event": "An event another person organized",
        "sends": "A message sent in the user's name"
      }
    },
    "reply_complete": {
      "hook": "output",
      "type": "probability",
      "instructions": "The reply answers every question the request asks."
    }
  },
  "rules": [
    {
      "question": "ambiguous_reference",
      "op": ">=",
      "action": "ask",
      "threshold": "ask"
    },
    {
      "question": "multi_event_limit",
      "op": ">=",
      "action": "deliberate",
      "threshold": "deliberate"
    },
    {
      "question": "consequence",
      "op": "not_in",
      "action": "confirm",
      "value": [
        "none"
      ]
    },
    {
      "question": "reply_complete",
      "op": "<",
      "action": "revise",
      "threshold": "revise"
    }
  ]
}

